import React from "react";
import { useNavigate } from "react-router-dom";
import "./adpage.css"; // Assuming you're using a separate CSS file

const AdPage = () => {
  const navigate = useNavigate();

  const topProducts = [
    {
      title: "Smartphone",
      desc: "Latest 5G smartphone with AMOLED display",
      img: "https://source.unsplash.com/300x200/?smartphone",
    },
    {
      title: "Wireless Headphones",
      desc: "Noise-cancelling over-ear headphones",
      img: "https://source.unsplash.com/300x200/?headphones",
    },
    {
      title: "Gaming Laptop",
      desc: "High-performance laptop for gaming and work",
      img: "https://source.unsplash.com/300x200/?laptop",
    },
  ];

  const topBrands = [
    {
      title: "Nike",
      desc: "Top sports brand products",
      img: "https://source.unsplash.com/300x200/?nike,shoes",
    },
    {
      title: "Apple",
      desc: "Premium gadgets and accessories",
      img: "https://source.unsplash.com/300x200/?apple,macbook",
    },
    {
      title: "Samsung",
      desc: "Smartphones, TVs, and more",
      img: "https://source.unsplash.com/300x200/?samsung,tech",
    },
  ];

  return (
    <div className="adpage">
      {/* Banner */}
      <div className="ad-banner">
        <img
          src="https://source.unsplash.com/1200x300/?shopping,ecommerce,sale"
          alt="Ad Banner"
        />
      </div>

      {/* Top Products */}
      <h2 className="section-title">Top Products</h2>
      <div className="card-list">
        {topProducts.map((card, i) => (
          <div
            className="product-card"
            key={i}
            onClick={() => navigate("/products")}
          >
            <img src={card.img} alt={card.title} />
            <h3>{card.title}</h3>
            <p>{card.desc}</p>
          </div>
        ))}
      </div>

      {/* Top Brands */}
      <h2 className="section-title">Top Brands</h2>
      <div className="card-list">
        {topBrands.map((card, i) => (
          <div
            className="product-card"
            key={i}
            onClick={() => navigate("/products")}
          >
            <img src={card.img} alt={card.title} />
            <h3>{card.title}</h3>
            <p>{card.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdPage;
